import heapq
g={1:[3],2:[3,4],3:[5],4:[5],5:[]}
degree={v:0 for v in g}
for neighbors in g.values():
    for u in neighbors:
        degree[u]+=1
h=[v for v in g if degree[v]==0]
heapq.heapify(h)
out=[]
while h:
    v=heapq.heappop(h)
    out.append(v)
    for u in g[v]:
        degree[u]-=1
        if degree[u]==0:
            heapq.heappush(h,u)
print(out)

g={"A":["B"],"B":["C"],"C":["A"]}
color={v:0 for v in g}
def cycle(v):
    color[v]=1
    for u in g[v]:
        if color[u]==1 or (color[u]==0 and cycle(u)):
            return True
    color[v]=2
    return False
print(cycle("A"))

